        private const val POLL_INTERVAL = 30L // in seconds (increased slightly to balance responsiveness and battery)
        private const val NOTIFICATION_CHANNEL_MESSAGES = "NOTIFICATION_CHANNEL_MESSAGES"
        private const val NOTIFICATION_CHANNEL_SERVICE = "NOTIFICATION_CHANNEL_SERVICE"
        private const val NOTIFICATION_CHANNEL_PERIODIC = "NOTIFICATION_CHANNEL_PERIODIC"
        private const val FOREGROUND_SERVICE_NOTIFICATION_ID = 4343
        private const val PERIODIC_NOTIFICATION_ID = 5555
        private const val NOTIFICATION_API_ENDPOINT = "/ocs/v2.php/apps/notifications/api/v2/notifications"
        
        // Increase message age threshold to 12 hours to ensure we don't miss messages
        private const val MESSAGE_AGE_THRESHOLD_MS = 43200000L // 12 hours
        
        // Periodic notification interval (in milliseconds)
        private const val PERIODIC_NOTIFICATION_INTERVAL = 60000L // 1 minute
    }

    @Inject
    lateinit var userManager: UserManager

    @Inject
    lateinit var ncApi: NcApi

    private val serviceScope = CoroutineScope(Dispatchers.IO)
    private var pollingJob: Job? = null
    private var periodicJob: Job? = null
    private val disposables = CompositeDisposable()
    
    // Cache of processed notification IDs with timestamps
    private val processedNotifications = ConcurrentHashMap<Int, Long>()
    
    // Notification coordinator
    private lateinit var notificationCoordinator: NotificationCoordinator
    
    // Wake lock to keep CPU active during polling
    private var wakeLock: PowerManager.WakeLock? = null

    override fun onCreate() {
        super.onCreate()
        NextcloudTalkApplication.sharedApplication?.componentApplication?.inject(this)
        createNotificationChannels()
        
        // Initialize notification coordinator
        notificationCoordinator = NotificationCoordinator.getInstance(applicationContext)
        
        // Initialize wake lock
        val powerManager = getSystemService(Context.POWER_SERVICE) as PowerManager
        wakeLock = powerManager.newWakeLock(
            PowerManager.PARTIAL_WAKE_LOCK,
            "NotificationPolling:WakeLock"
        )
        wakeLock?.setReferenceCounted(false)
        
        Log.d(TAG, "NotificationPollingService created")
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        try {
            // Start as foreground service for Android 8.0+
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                startForeground(FOREGROUND_SERVICE_NOTIFICATION_ID, createForegroundNotification())
            }
            
            // If we're already polling, don't start another job
            if (pollingJob?.isActive == true) {
                return START_STICKY
            }
            
            startPolling()
            
            // Start periodic notifications
            startPeriodicNotifications()
        } catch (e: Exception) {
            Log.e(TAG, "Error in onStartCommand", e)
        }
        
        // Using START_STICKY to ensure service restarts if killed
        return START_STICKY
    }

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onDestroy() {
        stopPolling()
        stopPeriodicNotifications()
        disposables.dispose()
        if (wakeLock?.isHeld == true) {
            try {
                wakeLock?.release()
            } catch (e: Exception) {
                Log.e(TAG, "Error releasing wake lock", e)
            }
        }
        super.onDestroy()
    }
    
    private fun createNotificationChannels() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val notificationManager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            
            // Chat messages notification channel
            val messageChannel = NotificationChannel(
                NOTIFICATION_CHANNEL_MESSAGES,
                "Chat messages",
                NotificationManager.IMPORTANCE_HIGH
            ).apply {
                description = "Notifications for chat messages"
                enableLights(true)
                lightColor = Color.BLUE
                enableVibration(true)
                setShowBadge(true)
            }
            notificationManager.createNotificationChannel(messageChannel)
            
            // Service notification channel (lower importance)
            val serviceChannel = NotificationChannel(
                NOTIFICATION_CHANNEL_SERVICE,
                "Notification Polling Service",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Required for notifications to work properly"
                setShowBadge(false)
            }
            notificationManager.createNotificationChannel(serviceChannel)
            
            // Periodic notification channel
            val periodicChannel = NotificationChannel(
                NOTIFICATION_CHANNEL_PERIODIC,
                "Periodic Notifications",
                NotificationManager.IMPORTANCE_HIGH
            ).apply {
                description = "Periodic notifications to ensure delivery"
                setShowBadge(true)
                enableLights(true)
                lightColor = Color.RED
                enableVibration(true)
                vibrationPattern = longArrayOf(0, 250, 250, 250)
                lockscreenVisibility = Notification.VISIBILITY_PUBLIC
                
                // Force full screen importance
                setBypassDnd(true) // Bypass Do Not Disturb mode
            }
            notificationManager.createNotificationChannel(periodicChannel)
        }
    }
    
    private fun createForegroundNotification(): Notification {
        val pendingIntent = PendingIntent.getActivity(
            this,
            0,
            Intent(this, MainActivity::class.java),
            PendingIntent.FLAG_IMMUTABLE
        )
        
        return NotificationCompat.Builder(this, NOTIFICATION_CHANNEL_SERVICE)
            .setContentTitle("Nextcloud Talk")
            .setContentText("Checking for new messages")
            .setSmallIcon(R.drawable.ic_notification)
            .setContentIntent(pendingIntent)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .setOngoing(true)
            .build()
    }
    
    private fun startPolling() {
        Log.d(TAG, "Starting notification polling")
        
        pollingJob = serviceScope.launch {
            // Get current user
            val currentUser = userManager.currentUser?.blockingGet()
            if (currentUser == null) {
                Log.e(TAG, "No current user found, stopping service")
                stopSelf()
                return@launch
            }
            
            Log.d(TAG, "Started notification polling for user ${currentUser.id ?: 0L}")
            
            // Start polling with wake lock protection
            while (true) {
                try {
                    // Acquire wake lock before polling
                    try {
                        if (wakeLock?.isHeld == false) {
                            wakeLock?.acquire(1 * 60 * 1000L) // 1 minute max
                        }
                    } catch (e: Exception) {
                        Log.e(TAG, "Error acquiring wake lock", e)
                    }
                    
                    pollForNotifications(currentUser)
                    
                    // Release wake lock after polling
                    try {
                        if (wakeLock?.isHeld == true) {
                            wakeLock?.release()
                        }
                    } catch (e: Exception) {
                        Log.e(TAG, "Error releasing wake lock", e)
                    }
                } catch (e: Exception) {
                    Log.e(TAG, "Error during notification polling", e)
                    // Always make sure to release the wake lock
                    try {
                        if (wakeLock?.isHeld == true) {
                            wakeLock?.release()
                        }
                    } catch (e2: Exception) {
                        Log.e(TAG, "Error releasing wake lock after exception", e2)
                    }
                }
                delay(TimeUnit.SECONDS.toMillis(POLL_INTERVAL))
            }
        }
    }
    
    private fun stopPolling() {
        pollingJob?.cancel()
        pollingJob = null
        
        Log.d(TAG, "Stopped notification polling service")
    }
    
    private suspend fun pollForNotifications(user: User) {
        try {
            val currentTime = System.currentTimeMillis()
            
            // Clean up old processed notifications (older than 12 hours)
            cleanupOldNotifications(currentTime - TimeUnit.HOURS.toMillis(12))
            
            // Check if user object is valid
            if (user.baseUrl.isNullOrEmpty() || user.token.isNullOrEmpty() || user.username.isNullOrEmpty()) {
                Log.e(TAG, "Invalid user data for notification polling")
                return
            }
            
            // Prepare the API request
            val credentials = ApiUtils.getCredentials(user.username, user.token)
            val baseUrl = user.baseUrl
            
            // Log the API request for debugging
            Log.d(TAG, "Polling notifications API at: $baseUrl$NOTIFICATION_API_ENDPOINT")
            
            // Execute the API request
            val request = ncApi.getNotifications(
                credentials,
                ApiUtils.getAcceptHeader()
            )
            
            disposables.add(
                request
                    .subscribeOn(Schedulers.io())
                    .observeOn(AndroidSchedulers.mainThread())
                    .subscribe(
                        { response -> 
                            Log.d(TAG, "Received API response, code: ${response.code()}")
                            handleNotificationsResponse(response, user) 
                        },
                        { error -> 
                            Log.e(TAG, "Error fetching notifications: ${error.message}", error)
                        }
                    )
            )
            
        } catch (e: Exception) {
            Log.e(TAG, "Error during notification polling", e)
        }
    }
    
    private fun handleNotificationsResponse(response: Response<String>, user: User) {
        try {
            if (!response.isSuccessful) {
                Log.e(TAG, "Error fetching notifications: ${response.code()} - ${response.message()}")
                return
            }
            
            val responseBody = response.body() ?: return
            Log.d(TAG, "Notification API response received, length: ${responseBody.length}")
            
            // Log full response for debugging (truncated for large responses)
            if (responseBody.length < 1000) {
                Log.d(TAG, "Full response: $responseBody")
            } else {
                Log.d(TAG, "Response (truncated): ${responseBody.take(1000)}...")
            }
            
            try {
                val jsonResponse = JSONObject(responseBody)
                val ocs = jsonResponse.optJSONObject("ocs")
                
                if (ocs == null) {
                    Log.e(TAG, "Invalid response format: missing 'ocs' object")
                    return
                }
                
                val meta = ocs.optJSONObject("meta")
                val statusCode = meta?.optInt("statuscode", 0) ?: 0
                val status = meta?.optString("status", "unknown") ?: "unknown"
                
                Log.d(TAG, "API Response status: $status ($statusCode)")
                
                val data = ocs.optJSONArray("data")
                if (data == null) {
                    Log.e(TAG, "Invalid response format: missing 'data' array")
                    return
                }
                
                Log.d(TAG, "Found ${data.length()} notifications in the response")
                
                // Process each notification
                for (i in 0 until data.length()) {
                    val notification = data.optJSONObject(i)
                    if (notification != null) {
                        processNotification(notification, user)
                    }
                }
                
            } catch (e: Exception) {
                Log.e(TAG, "Error parsing JSON response", e)
                // Log part of the response that might have caused the error
                Log.e(TAG, "Problematic response: ${responseBody.take(200)}...")
            }
            
        } catch (e: Exception) {
            Log.e(TAG, "Error processing notifications response", e)
        }
    }
    
    private fun processNotification(notification: JSONObject, user: User) {
        try {
            // Extract notification data
            val notificationId = notification.optInt("notification_id", 0)
            val app = notification.optString("app", "")
            val objectType = notification.optString("object_type", "")
            
            // Debug: Log raw notification JSON
            Log.d(TAG, "GOT NOTIFICATION: $notification")
            
            // Only process Talk (spreed) notifications
            if (app != "spreed") {
                Log.d(TAG, "Skipping notification $notificationId from app '$app' - not a Talk notification")
                return
            }
            
            // Get notification details
            val message = notification.optString("message", "New message")
            val subject = notification.optString("subject", "New conversation message")
            val objectId = notification.optString("object_id", "")
            val link = notification.optString("link", "")
            
            // Log full details of the Talk notification for debugging
            Log.d(TAG, "TALK NOTIFICATION DETAILS - ID: $notificationId")
            Log.d(TAG, "- Message: $message")
            Log.d(TAG, "- Subject: $subject")
            Log.d(TAG, "- ObjectID: $objectId")
            Log.d(TAG, "- Link: $link")
            
            // Extract room token from objectId or link
            var roomToken = ""
            
            // Try to extract from objectId first (format is usually "roomToken/messageId")
            if (objectId.contains("/")) {
                roomToken = objectId.split("/").firstOrNull() ?: ""
            }
            
            // If that fails, try to extract from the link
            if (roomToken.isEmpty() && link.isNotEmpty()) {
                // Links typically contain the room token in the format /call/{roomToken}
                val callPattern = "/call/([^/?]+)".toRegex()
                val match = callPattern.find(link)
                if (match != null) {
                    roomToken = match.groupValues[1]
                }
            }
            
            // If we still don't have a room token, log and return
            if (roomToken.isEmpty()) {
                Log.w(TAG, "Could not extract room token from notification ID: $notificationId - ObjectID: $objectId, Link: $link")
                return
            }
            
            Log.d(TAG, "Extracted room token: $roomToken")
            
            // Check if we processed this notification recently (within last 30 seconds)
            val lastProcessed = processedNotifications[notificationId]
            val now = System.currentTimeMillis()
            
            if (lastProcessed != null && now - lastProcessed < 30000) {
                Log.d(TAG, "Notification $notificationId already processed recently, skipping")
                return
            }
            
            // Store this notification as processed
            processedNotifications[notificationId] = now
            
            // Get notification coordinator to check if we should display this notification
            val notificationCoordinator = NotificationCoordinator.getInstance(applicationContext)
            
            // Only suppress notification if we're actively in this conversation
            if (notificationCoordinator.isInConversation(roomToken)) {
                Log.d(TAG, "User is actively in conversation $roomToken, skipping notification")
                return
            }
            
            // Check notification permission before attempting to create notification
            val hasPermission = hasNotificationPermission()
            Log.d(TAG, "Creating notification for room $roomToken - Has notification permission: $hasPermission")
            
            // Create a notification with more details
            val timestamp = System.currentTimeMillis()
            
            // Extract sender name if available, or use a default
            val senderName = subject.takeIf { it.isNotEmpty() } ?: "Nextcloud Talk"
            val conversationName = notification.optString("object_name", "Chat").takeIf { it.isNotEmpty() } ?: roomToken
            
            // Create and show the notification
            createChatNotification(user, roomToken, message, senderName, conversationName, timestamp)
            
            // Broadcast the message update to refresh the conversation list
            notificationCoordinator.broadcastMessageUpdate(roomToken, timestamp)
            
            Log.d(TAG, "Successfully processed and created notification for room: $roomToken")
            
        } catch (e: Exception) {
            Log.e(TAG, "Error processing notification", e)
        }
    }
    
    private fun cleanupOldNotifications(threshold: Long) {
        val iterator = processedNotifications.entries.iterator()
        while (iterator.hasNext()) {
            val entry = iterator.next()
            if (entry.value < threshold) {
                iterator.remove()
            }
        }
    }
    
    private fun hasNotificationPermission(): Boolean {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            val permissionCheck = ContextCompat.checkSelfPermission(
                applicationContext,
                android.Manifest.permission.POST_NOTIFICATIONS
            )
            return permissionCheck == android.content.pm.PackageManager.PERMISSION_GRANTED
        }
        return true // Permission automatically granted on API < 33
    }
    
    private fun createChatNotification(
        user: User, 
        roomToken: String, 
        message: String, 
        sender: String,
        conversationName: String,
        timestamp: Long
    ) {
        // Check notification permission first
        if (!hasNotificationPermission()) {
            Log.w(TAG, "Cannot show notification: permission not granted")
            
            // Debug: Log more information about the failed notification
            Log.d(TAG, "SKIPPED NOTIFICATION - Room: $roomToken, Sender: $sender, Message: $message")
            
            // Still broadcast message update even without permission
            notificationCoordinator.broadcastMessageUpdate(roomToken, timestamp)
            return
        }
        
        // Generate a notification ID based on room token
        val notificationId = calculateCRC32(roomToken).toInt()
        
        Log.d(TAG, "CREATING NOTIFICATION - Room: $roomToken, ID: $notificationId, Message: $message, Sender: $sender")
        
        val pendingIntent = Intent(this, MainActivity::class.java).let { notificationIntent ->
            notificationIntent.putExtra(BundleKeys.KEY_ROOM_TOKEN, roomToken)
            notificationIntent.putExtra(BundleKeys.KEY_INTERNAL_USER_ID, user.id ?: 0L)
            notificationIntent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)
            
            PendingIntent.getActivity(
                this, 
                System.currentTimeMillis().toInt(), 
                notificationIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
        }
        
        // Create a unique channel ID for each conversation to ensure reliable delivery
        val channelId = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val uniqueChannelId = "CHAT_CHANNEL_$roomToken"
            val notificationManager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            
            // Check if channel exists; if not, create it
            if (notificationManager.getNotificationChannel(uniqueChannelId) == null) {
                val channel = NotificationChannel(
                    uniqueChannelId,
                    "Chat: $conversationName",
                    NotificationManager.IMPORTANCE_HIGH
                )
                channel.description = "Notifications for chat: $conversationName"
                channel.enableLights(true)
                channel.enableVibration(true)
                notificationManager.createNotificationChannel(channel)
                Log.d(TAG, "Created notification channel $uniqueChannelId for room $roomToken")
            }
            
            uniqueChannelId
        } else {
            NOTIFICATION_CHANNEL_MESSAGES
        }
        
        val notificationBuilder = NotificationCompat.Builder(this, channelId)
            .setSmallIcon(R.drawable.ic_notification)
            .setContentTitle(sender)
            .setContentText(message)
            .setSubText(conversationName)
            .setContentIntent(pendingIntent)
            .setAutoCancel(true)
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
            .setCategory(NotificationCompat.CATEGORY_MESSAGE)
            .setDefaults(NotificationCompat.DEFAULT_ALL) // Enable sound, vibration and lights
        
        val notificationManager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        notificationManager.notify(notificationId, notificationBuilder.build())
        
        Log.d(TAG, "NOTIFICATION SENT - Room: $roomToken, ID: $notificationId, Sender: $sender")
    }
    
    private fun calculateCRC32(data: String): Long {
        val crc = CRC32()
        crc.update(data.toByteArray())
        return crc.value
    }
    
