        Log.d(TAG, "Checking active chats for new messages")
    }
    
    private fun startPeriodicNotifications() {
        Log.d(TAG, "Starting periodic notifications")
        
        periodicJob = serviceScope.launch {
            while (true) {
                try {
                    Log.d(TAG, "Sending periodic notification")
                    sendPeriodicNotification()
                } catch (e: Exception) {
                    Log.e(TAG, "Error sending periodic notification", e)
                }
                
                delay(PERIODIC_NOTIFICATION_INTERVAL)
            }
        }
    }
    
    private fun stopPeriodicNotifications() {
        periodicJob?.cancel()
        periodicJob = null
        
        Log.d(TAG, "Stopped periodic notifications")
    }
    
    private fun sendPeriodicNotification() {
        if (!hasNotificationPermission()) {
            Log.w(TAG, "Cannot show periodic notification: permission not granted")
            return
        }
        
        try {
            val currentUser = userManager.currentUser?.blockingGet()
            if (currentUser == null) {
                Log.e(TAG, "No current user found, cannot send periodic notification")
                return
            }
            
            val username = currentUser.username ?: "User"
            val timestamp = System.currentTimeMillis()
            val date = java.text.SimpleDateFormat("HH:mm:ss", java.util.Locale.getDefault()).format(java.util.Date())
            
            val pendingIntent = Intent(this, MainActivity::class.java).let { notificationIntent ->
                notificationIntent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)
                
                PendingIntent.getActivity(
                    this, 
                    System.currentTimeMillis().toInt(), 
                    notificationIntent,
                    PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                )
            }
            
            // Create a full-screen intent for high visibility
            val fullScreenIntent = Intent(this, MainActivity::class.java).let { fullScreenIntent ->
                fullScreenIntent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
                
                PendingIntent.getActivity(
                    this,
                    System.currentTimeMillis().toInt() + 1,
                    fullScreenIntent,
                    PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                )
            }
            
            val channelId = NOTIFICATION_CHANNEL_PERIODIC
            
            val notificationBuilder = NotificationCompat.Builder(this, channelId)
                .setSmallIcon(R.drawable.ic_notification)
                .setContentTitle("New Message Alert")
                .setContentText("You have a new message at $date")
                .setContentIntent(pendingIntent)
                .setFullScreenIntent(fullScreenIntent, true) // Force heads-up notification
                .setAutoCancel(true)
                .setPriority(NotificationCompat.PRIORITY_HIGH) // Use HIGH priority
                .setCategory(NotificationCompat.CATEGORY_MESSAGE) // Use MESSAGE category
                .setVisibility(NotificationCompat.VISIBILITY_PUBLIC) 
                .setDefaults(NotificationCompat.DEFAULT_ALL) // Enable sound, vibration and lights
                
            // Add specific flags for heads-up display
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
                notificationBuilder.setVibrate(longArrayOf(0, 250, 250, 250)) // Custom vibration pattern
            }
            
            val notificationManager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            notificationManager.notify(PERIODIC_NOTIFICATION_ID, notificationBuilder.build())
            
            Log.d(TAG, "Periodic HIGH-PRIORITY notification sent at $date")
        } catch (e: Exception) {
            Log.e(TAG, "Error creating periodic notification", e)
        }
    }
